class _TailState:
    """Remembers what a polling tail has delivered (bounded to the newest timestamp)."""

    def __init__(self, start: datetime | None) -> None:
        self.since = start
        self._seen: set[tuple[str, str, str | None]] = set()

    def fresh(self, records: list[LogRecord]) -> list[LogRecord]:
        out: list[LogRecord] = []
        for record in sorted(records, key=lambda r: r.timestamp):
            key = (record.timestamp.isoformat(), record.body, record.span_id)
            if key in self._seen or (self.since is not None and record.timestamp < self.since):
                continue
            if self.since is None or record.timestamp > self.since:
                self.since = record.timestamp
                self._seen = set()
            self._seen.add(key)
            out.append(record)
        return out


